changeSet.sql:
create table if not exists kb_launcher_group ( id bigint primary key, lastmodifieddate timestamp with time zone default now(), creationdate timestamp with time zone default now(), lastmodifieduser bigint references users(id) on delete set null, state integer default 1, domain_id bigint references domain(id) on delete cascade,
alias character varying(256) not null, name character varying(256) not null, description character varying(2048), position integer default 0
);
alter table wf_launcher add column if not exists launchergroup_id bigint references kb_launcher_group(id) on delete restrict;
create index if not exists launcher_group_domain_idx on kb_launcher_group (domain_id, lower(name));

insert into  kb_launcher_group (id, lastmodifieduser, domain_id, name, alias, position) select nextval('objectid_sequence'), (select id from users where username= concat('root@', d.name)), d.id, 'Compliance', 'compliance',0             from domain d;	   
insert into  kb_launcher_group (id, lastmodifieduser, domain_id, name, alias, position) select nextval('objectid_sequence'), (select id from users where username= concat('root@', d.name)), d.id, 'Corporate', 'corporate',1               from domain d;
insert into  kb_launcher_group (id, lastmodifieduser, domain_id, name, alias, position) select nextval('objectid_sequence'), (select id from users where username= concat('root@', d.name)), d.id, 'Asset Management', 'asset-management',2 from domain d;

alter table dataset 					add column if not exists onlyroot boolean default false;
alter table kb_classifier 				add column if not exists onlyroot boolean default false;
alter table kb_attribute 				add column if not exists onlyroot boolean default false;
alter table kb_contenttemplate 			add column if not exists onlyroot boolean default false;

alter table KB_AttributeTemplate add column if not exists parent_id bigint;
ALTER TABLE ONLY KB_AttributeTemplate DROP CONSTRAINT parent_fk;
ALTER TABLE ONLY KB_AttributeTemplate ADD CONSTRAINT parent_fk FOREIGN KEY (parent_id) REFERENCES kb_classifier(id) ON DELETE RESTRICT;

